{
  "name": "Gestão de Pagamentos - Obra",
  "description": "Sistema intuitivo para controle de frequência e cálculo de pagamentos semanais para pedreiros e ajudantes, com suporte a recibos gerados por IA."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum WorkerType {
  PEDREIRO = 'Pedreiro',
  AJUDANTE = 'Ajudante'
}

export interface Attendance {
  monday: boolean;
  tuesday: boolean;
  wednesday: boolean;
  thursday: boolean;
  friday: boolean;
  saturday: boolean;
}

export interface Worker {
  id: string;
  name: string;
  role: WorkerType;
  dailyRate: number;
  attendance: Attendance;
}

export interface WeeklyPayment {
  id: string;
  startDate: string;
  endDate: string;
  workers: Worker[];
  totalAmount: number;
}

export const DAYS_OF_WEEK = [
  { key: 'monday', label: 'Seg' },
  { key: 'tuesday', label: 'Ter' },
  { key: 'wednesday', label: 'Qua' },
  { key: 'thursday', label: 'Qui' },
  { key: 'friday', label: 'Sex' },
  { key: 'saturday', label: 'Sáb' },
] as const;

import { GoogleGenAI } from "@google/genai";
import { WeeklyPayment } from "../types";

export const generateReceiptText = async (payment: WeeklyPayment): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const workerSummary = payment.workers.map(w => {
    const daysWorked = Object.values(w.attendance).filter(Boolean).length;
    const total = daysWorked * w.dailyRate;
    return `- ${w.name} (${w.role}): ${daysWorked} dias trabalhados x R$ ${w.dailyRate} = R$ ${total.toFixed(2)}`;
  }).join('\n');

  const prompt = `
    Aja como um administrador de obras profissional. 
    Gere um texto curto e educado para ser enviado via WhatsApp confirmando o pagamento da semana.
    Período: ${payment.startDate} a ${payment.endDate}.

    Resumo dos pagamentos:
    ${workerSummary}

    Total Geral da Semana: R$ ${payment.totalAmount.toFixed(2)}

    O texto deve ser claro, profissional e incluir os valores individuais e o total.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Erro ao gerar recibo.";
  } catch (error) {
    console.error("Error generating receipt:", error);
    return "Desculpe, não foi possível gerar o recibo automático agora.";
  }
};

import React, { useState, useEffect, useCallback } from 'react';
import { Worker, WorkerType, WeeklyPayment, DAYS_OF_WEEK, Attendance } from './types';
import { generateReceiptText } from './services/geminiService';
import { 
  Users, 
  Calendar, 
  Plus, 
  Trash2, 
  Save, 
  MessageSquare, 
  TrendingUp, 
  CheckSquare, 
  History as HistoryIcon,
  ChevronRight,
  Calculator
} from 'lucide-react';

const INITIAL_WORKERS: Worker[] = [
  {
    id: '1',
    name: 'Acidio',
    role: WorkerType.PEDREIRO,
    dailyRate: 180,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  },
  {
    id: '2',
    name: 'Neto',
    role: WorkerType.AJUDANTE,
    dailyRate: 120,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  }
];

const App: React.FC = () => {
  const [workers, setWorkers] = useState<Worker[]>(() => {
    const saved = localStorage.getItem('current_week_workers');
    return saved ? JSON.parse(saved) : INITIAL_WORKERS;
  });

  const [history, setHistory] = useState<WeeklyPayment[]>(() => {
    const saved = localStorage.getItem('payment_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'current' | 'history'>('current');
  const [isGeneratingReceipt, setIsGeneratingReceipt] = useState(false);
  const [receiptText, setReceiptText] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('current_week_workers', JSON.stringify(workers));
  }, [workers]);

  useEffect(() => {
    localStorage.setItem('payment_history', JSON.stringify(history));
  }, [history]);

  const toggleAttendance = (workerId: string, day: keyof Attendance) => {
    setWorkers(prev => prev.map(w => 
      w.id === workerId 
        ? { ...w, attendance: { ...w.attendance, [day]: !w.attendance[day] } }
        : w
    ));
  };

  const calculateWorkerTotal = (worker: Worker) => {
    const daysWorked = Object.values(worker.attendance).filter(Boolean).length;
    return daysWorked * worker.dailyRate;
  };

  const calculateGrandTotal = () => {
    return workers.reduce((acc, w) => acc + calculateWorkerTotal(w), 0);
  };

  const handleSaveWeek = () => {
    const total = calculateGrandTotal();
    if (total === 0) {
      alert("Nenhum dia de trabalho registrado!");
      return;
    }

    const today = new Date();
    const lastMonday = new Date(today);
    lastMonday.setDate(today.getDate() - (today.getDay() === 0 ? 6 : today.getDay() - 1));

    const newPayment: WeeklyPayment = {
      id: Date.now().toString(),
      startDate: lastMonday.toLocaleDateString('pt-BR'),
      endDate: today.toLocaleDateString('pt-BR'),
      workers: JSON.parse(JSON.stringify(workers)),
      totalAmount: total
    };

    setHistory(prev => [newPayment, ...prev]);
    // Reset attendance for next week
    setWorkers(prev => prev.map(w => ({
      ...w,
      attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
    })));
    alert("Semana salva com sucesso!");
  };

  const handleGenerateReceipt = async () => {
    setIsGeneratingReceipt(true);
    setReceiptText(null);

    const today = new Date();
    const lastMonday = new Date(today);
    lastMonday.setDate(today.getDate() - (today.getDay() === 0 ? 6 : today.getDay() - 1));

    const tempPayment: WeeklyPayment = {
      id: 'temp',
      startDate: lastMonday.toLocaleDateString('pt-BR'),
      endDate: today.toLocaleDateString('pt-BR'),
      workers: workers,
      totalAmount: calculateGrandTotal()
    };

    const text = await generateReceiptText(tempPayment);
    setReceiptText(text);
    setIsGeneratingReceipt(false);
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-yellow-500 text-slate-900 shadow-md sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-6 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Calculator className="w-8 h-8" />
            <h1 className="text-2xl font-bold tracking-tight">Gestão de Obra</h1>
          </div>
          <nav className="flex bg-yellow-600 rounded-lg p-1">
            <button 
              onClick={() => setView('current')}
              className={`px-4 py-2 rounded-md transition-colors ${view === 'current' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Semana Atual
            </button>
            <button 
              onClick={() => setView('history')}
              className={`px-4 py-2 rounded-md transition-colors ${view === 'history' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Histórico
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 mt-8">
        {view === 'current' ? (
          <div className="space-y-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2 text-slate-600">
                <Calendar className="w-5 h-5" />
                <span className="font-medium">Resumo da Frequência</span>
              </div>
              <div className="text-sm text-slate-500 bg-white px-3 py-1 rounded-full border">
                R$ 180 (Acidio) | R$ 120 (Neto)
              </div>
            </div>

            {workers.map(worker => (
              <div key={worker.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <div>
                    <h3 className="font-bold text-lg text-slate-800">{worker.name}</h3>
                    <p className="text-sm text-slate-500">{worker.role} • R$ {worker.dailyRate}/dia</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-slate-400 uppercase font-bold">Total Parcial</p>
                    <p className="text-xl font-bold text-yellow-600">R$ {calculateWorkerTotal(worker).toFixed(2)}</p>
                  </div>
                </div>

                <div className="p-4 grid grid-cols-3 sm:grid-cols-6 gap-3">
                  {DAYS_OF_WEEK.map(day => (
                    <button
                      key={day.key}
                      onClick={() => toggleAttendance(worker.id, day.key)}
                      className={`flex flex-col items-center justify-center p-3 rounded-lg border-2 transition-all ${
                        worker.attendance[day.key]
                          ? 'border-yellow-500 bg-yellow-50 text-yellow-700'
                          : 'border-slate-100 bg-white text-slate-400'
                      }`}
                    >
                      <span className="text-xs font-bold uppercase mb-1">{day.label}</span>
                      {worker.attendance[day.key] ? (
                        <CheckSquare className="w-5 h-5" />
                      ) : (
                        <div className="w-5 h-5 border-2 border-slate-200 rounded-sm" />
                      )}
                    </button>
                  ))}
                </div>
              </div>
            ))}

            {/* Current Summary Bar */}
            <div className="bg-slate-900 text-white rounded-xl p-6 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
              <div>
                <p className="text-slate-400 text-sm uppercase tracking-wider font-bold">Total da Semana</p>
                <h2 className="text-4xl font-extrabold">R$ {calculateGrandTotal().toFixed(2)}</h2>
              </div>
              <div className="flex gap-3 w-full md:w-auto">
                <button 
                  onClick={handleGenerateReceipt}
                  className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-slate-800 hover:bg-slate-700 text-white px-6 py-3 rounded-lg font-bold transition-colors"
                >
                  <MessageSquare className="w-5 h-5" />
                  Gerar Recibo
                </button>
                <button 
                  onClick={handleSaveWeek}
                  className="flex-1 md:flex-none flex items-center justify-center gap-2 bg-yellow-500 hover:bg-yellow-400 text-slate-900 px-6 py-3 rounded-lg font-bold transition-colors shadow-lg"
                >
                  <Save className="w-5 h-5" />
                  Fechar Semana
                </button>
              </div>
            </div>

            {/* Gemini Receipt Modal/Card */}
            {isGeneratingReceipt && (
              <div className="bg-white border-2 border-yellow-500 rounded-xl p-8 text-center animate-pulse">
                <p className="text-slate-600">Inteligência Artificial criando seu recibo profissional...</p>
              </div>
            )}

            {receiptText && (
              <div className="bg-yellow-50 border border-yellow-200 rounded-xl p-6 relative">
                <button 
                  onClick={() => setReceiptText(null)}
                  className="absolute top-4 right-4 text-slate-400 hover:text-slate-600"
                >
                  <Trash2 className="w-5 h-5" />
                </button>
                <h4 className="text-sm font-bold text-yellow-800 uppercase mb-3 flex items-center gap-2">
                  <MessageSquare className="w-4 h-4" />
                  Recibo Sugerido pela IA
                </h4>
                <div className="bg-white p-4 rounded-lg border border-yellow-100 text-slate-700 whitespace-pre-wrap text-sm italic">
                  {receiptText}
                </div>
                <div className="mt-4 flex gap-2">
                  <button 
                    onClick={() => {
                      navigator.clipboard.writeText(receiptText);
                      alert("Copiado!");
                    }}
                    className="text-xs bg-yellow-200 hover:bg-yellow-300 text-yellow-900 px-3 py-1 rounded font-bold uppercase"
                  >
                    Copiar para o WhatsApp
                  </button>
                </div>
              </div>
            )}
          </div>
        ) : (
          <div className="space-y-4">
            <div className="flex items-center gap-2 text-slate-600 mb-6">
              <HistoryIcon className="w-5 h-5" />
              <span className="font-medium">Histórico de Pagamentos</span>
            </div>

            {history.length === 0 ? (
              <div className="bg-white rounded-xl p-12 text-center border-2 border-dashed border-slate-200">
                <Users className="w-12 h-12 text-slate-300 mx-auto mb-4" />
                <p className="text-slate-500">Nenhum histórico disponível ainda.</p>
              </div>
            ) : (
              history.map(item => (
                <div key={item.id} className="bg-white rounded-xl border border-slate-200 p-5 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 hover:border-yellow-400 transition-colors cursor-pointer group">
                  <div className="flex items-center gap-4">
                    <div className="w-12 h-12 bg-yellow-100 text-yellow-700 rounded-full flex items-center justify-center font-bold">
                      {item.startDate.split('/')[0]}
                    </div>
                    <div>
                      <p className="font-bold text-slate-800">{item.startDate} — {item.endDate}</p>
                      <p className="text-sm text-slate-500">
                        {item.workers.map(w => `${w.name} (${Object.values(w.attendance).filter(Boolean).length}d)`).join(', ')}
                      </p>
                    </div>
                  </div>
                  <div className="flex items-center gap-4 w-full sm:w-auto justify-between sm:justify-end">
                    <span className="text-xl font-bold text-slate-900">R$ {item.totalAmount.toFixed(2)}</span>
                    <ChevronRight className="w-5 h-5 text-slate-300 group-hover:text-yellow-500 transition-colors" />
                  </div>
                </div>
              ))
            )}
          </div>
        )}
      </main>

      {/* Floating Quick Action */}
      {view === 'current' && (
        <div className="fixed bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-4 bg-white shadow-2xl rounded-full px-6 py-3 border border-slate-100 md:hidden">
          <div className="text-slate-900 font-bold">R$ {calculateGrandTotal().toFixed(2)}</div>
          <div className="w-px h-6 bg-slate-200"></div>
          <button onClick={handleSaveWeek} className="text-yellow-600 font-bold text-sm uppercase">Salvar</button>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Worker, WorkerType, WeeklyPayment, DAYS_OF_WEEK, Attendance } from './types';
import { generateReceiptText } from './services/geminiService';
import { jsPDF } from 'jspdf';
import { 
  Users, 
  Calendar, 
  Trash2, 
  Save, 
  MessageSquare, 
  CheckSquare, 
  History as HistoryIcon,
  ChevronRight,
  Calculator,
  FileText,
  Send
} from 'lucide-react';

const INITIAL_WORKERS: Worker[] = [
  {
    id: '1',
    name: 'Acidio',
    role: WorkerType.PEDREIRO,
    dailyRate: 180,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  },
  {
    id: '2',
    name: 'Neto',
    role: WorkerType.AJUDANTE,
    dailyRate: 120,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  }
];

const WHATSAPP_NUMBER = "5521997391438";

const App: React.FC = () => {
  const [workers, setWorkers] = useState<Worker[]>(() => {
    const saved = localStorage.getItem('current_week_workers');
    return saved ? JSON.parse(saved) : INITIAL_WORKERS;
  });

  const [history, setHistory] = useState<WeeklyPayment[]>(() => {
    const saved = localStorage.getItem('payment_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'current' | 'history'>('current');
  const [isProcessing, setIsProcessing] = useState(false);
  const [receiptText, setReceiptText] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('current_week_workers', JSON.stringify(workers));
  }, [workers]);

  useEffect(() => {
    localStorage.setItem('payment_history', JSON.stringify(history));
  }, [history]);

  const toggleAttendance = (workerId: string, day: keyof Attendance) => {
    setWorkers(prev => prev.map(w => 
      w.id === workerId 
        ? { ...w, attendance: { ...w.attendance, [day]: !w.attendance[day] } }
        : w
    ));
  };

  const calculateWorkerTotal = (worker: Worker) => {
    const daysWorked = Object.values(worker.attendance).filter(Boolean).length;
    return daysWorked * worker.dailyRate;
  };

  const calculateGrandTotal = () => {
    return workers.reduce((acc, w) => acc + calculateWorkerTotal(w), 0);
  };

  const generatePDF = (payment: WeeklyPayment) => {
    const doc = new jsPDF();
    const margin = 20;
    let y = 30;

    // Header
    doc.setFontSize(22);
    doc.setTextColor(33, 33, 33);
    doc.text('Recibo de Pagamento Semanal', margin, y);

    y += 10;
    doc.setFontSize(12);
    doc.setTextColor(100, 100, 100);
    doc.text(`Período: ${payment.startDate} a ${payment.endDate}`, margin, y);

    y += 15;
    doc.setDrawColor(200, 200, 200);
    doc.line(margin, y, 190, y);
    y += 10;

    // Workers Details
    payment.workers.forEach((worker) => {
      const daysWorked = DAYS_OF_WEEK.filter(d => worker.attendance[d.key as keyof Attendance]);
      const total = calculateWorkerTotal(worker);

      if (daysWorked.length > 0) {
        doc.setFontSize(14);
        doc.setTextColor(0, 0, 0);
        doc.setFont('helvetica', 'bold');
        doc.text(`${worker.name} (${worker.role})`, margin, y);

        y += 7;
        doc.setFontSize(11);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(80, 80, 80);

        const daysText = daysWorked.map(d => d.label).join(', ');
        doc.text(`Dias: ${daysText} (${daysWorked.length} dias)`, margin, y);

        y += 6;
        doc.text(`Valor Diária: R$ ${worker.dailyRate.toFixed(2)}`, margin, y);

        doc.setFont('helvetica', 'bold');
        doc.setTextColor(180, 120, 0);
        const subtotalText = `Subtotal: R$ ${total.toFixed(2)}`;
        const textWidth = doc.getTextWidth(subtotalText);
        doc.text(subtotalText, 190 - textWidth, y);

        y += 12;
        doc.setDrawColor(240, 240, 240);
        doc.line(margin, y, 190, y);
        y += 10;
      }
    });

    // Grand Total
    y += 5;
    doc.setFontSize(18);
    doc.setTextColor(0, 0, 0);
    const totalLabel = "TOTAL GERAL:";
    const totalValue = `R$ ${payment.totalAmount.toFixed(2)}`;
    doc.text(totalLabel, margin, y);
    const valWidth = doc.getTextWidth(totalValue);
    doc.text(totalValue, 190 - valWidth, y);

    // Footer
    y = 280;
    doc.setFontSize(10);
    doc.setTextColor(150, 150, 150);
    doc.text('Gerado via Gestão de Obra - Acidio & Equipe', margin, y);

    doc.save(`Recibo_Obra_${payment.endDate.replace(/\//g, '-')}.pdf`);
  };

  const handleSaveWeek = () => {
    const total = calculateGrandTotal();
    if (total === 0) {
      alert("Nenhum dia de trabalho registrado!");
      return;
    }

    const today = new Date();
    const lastMonday = new Date(today);
    lastMonday.setDate(today.getDate() - (today.getDay() === 0 ? 6 : today.getDay() - 1));

    const newPayment: WeeklyPayment = {
      id: Date.now().toString(),
      startDate: lastMonday.toLocaleDateString('pt-BR'),
      endDate: today.toLocaleDateString('pt-BR'),
      workers: JSON.parse(JSON.stringify(workers)),
      totalAmount: total
    };

    setHistory(prev => [newPayment, ...prev]);
    alert("Semana salva com sucesso no histórico!");
  };

  const handleGenerateReceipt = async () => {
    const total = calculateGrandTotal();
    if (total === 0) {
      alert("Por favor, marque pelo menos um dia trabalhado.");
      return;
    }

    setIsProcessing(true);
    setReceiptText(null);

    const today = new Date();
    const lastMonday = new Date(today);
    lastMonday.setDate(today.getDate() - (today.getDay() === 0 ? 6 : today.getDay() - 1));

    const currentPayment: WeeklyPayment = {
      id: 'current',
      startDate: lastMonday.toLocaleDateString('pt-BR'),
      endDate: today.toLocaleDateString('pt-BR'),
      workers: workers,
      totalAmount: total
    };

    try {
      // 1. Gerar PDF
      generatePDF(currentPayment);

      // 2. Gerar texto para WhatsApp via Gemini
      const text = await generateReceiptText(currentPayment);
      setReceiptText(text);

      // 3. Redirecionar para WhatsApp
      const waUrl = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`;
      window.open(waUrl, '_blank');

    } catch (error) {
      console.error("Erro no processo de recibo:", error);
      alert("Houve um erro ao processar o recibo, mas o PDF pode ter sido baixado.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-yellow-500 text-slate-900 shadow-md sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-6 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Calculator className="w-8 h-8" />
            <h1 className="text-2xl font-bold tracking-tight">Gestão de Obra</h1>
          </div>
          <nav className="flex bg-yellow-600 rounded-lg p-1">
            <button 
              onClick={() => setView('current')}
              className={`px-4 py-2 rounded-md transition-colors ${view === 'current' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Semana Atual
            </button>
            <button 
              onClick={() => setView('history')}
              className={`px-4 py-2 rounded-md transition-colors ${view === 'history' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Histórico
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 mt-8">
        {view === 'current' ? (
          <div className="space-y-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2 text-slate-600">
                <Calendar className="w-5 h-5" />
                <span className="font-medium">Resumo da Frequência</span>
              </div>
              <div className="text-sm text-slate-500 bg-white px-3 py-1 rounded-full border">
                R$ 180 (Acidio) | R$ 120 (Neto)
              </div>
            </div>

            {workers.map(worker => (
              <div key={worker.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <div>
                    <h3 className="font-bold text-lg text-slate-800">{worker.name}</h3>
                    <p className="text-sm text-slate-500">{worker.role} • R$ {worker.dailyRate}/dia</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-slate-400 uppercase font-bold">Total Parcial</p>
                    <p className="text-xl font-bold text-yellow-600">R$ {calculateWorkerTotal(worker).toFixed(2)}</p>
                  </div>
                </div>

                <div className="p-4 grid grid-cols-3 sm:grid-cols-6 gap-3">
                  {DAYS_OF_WEEK.map(day => (
                    <button
                      key={day.key}
