import React, { useState, useEffect } from 'react';
import { Worker, WorkerType, WeeklyPayment, DAYS_OF_WEEK, Attendance } from './types';
import { generateReceiptText } from './services/geminiService';
import { jsPDF } from 'jspdf';
import { 
  Users, 
  Calendar, 
  Trash2, 
  Save, 
  MessageSquare, 
  CheckSquare, 
  History as HistoryIcon,
  ChevronRight,
  Calculator,
  FileText,
  Send
} from 'lucide-react';

const INITIAL_WORKERS: Worker[] = [
  {
    id: '1',
    name: 'Acidio',
    role: WorkerType.PEDREIRO,
    dailyRate: 180,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  },
  {
    id: '2',
    name: 'Neto',
    role: WorkerType.AJUDANTE,
    dailyRate: 120,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  }
];

const WHATSAPP_NUMBER = "5521997391448";

const App: React.FC = () => {
  const [workers, setWorkers] = useState<Worker[]>(() => {
    const saved = localStorage.getItem('current_week_workers');
    return saved ? JSON.parse(saved) : INITIAL_WORKERS;
  });

  const [history, setHistory] = useState<WeeklyPayment[]>(() => {
    const saved = localStorage.getItem('payment_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'current' | 'history'>('current');
  const [isProcessing, setIsProcessing] = useState(false);
  const [receiptText, setReceiptText] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('current_week_workers', JSON.stringify(workers));
  }, [workers]);

  useEffect(() => {
    localStorage.setItem('payment_history', JSON.stringify(history));
  }, [history]);

  const toggleAttendance = (workerId: string, day: keyof Attendance) => {
    setWorkers(prev => prev.map(w => 
      w.id === workerId 
        ? { ...w, attendance: { ...w.attendance, [day]: !w.attendance[day] } }
        : w
    ));
  };

  const calculateWorkerTotal = (worker: Worker) => {
    const daysWorked = Object.values(worker.attendance).filter(Boolean).length;
    return daysWorked * worker.dailyRate;
  };

  const calculateGrandTotal = () => {
    return workers.reduce((acc, w) => acc + calculateWorkerTotal(w), 0);
  };

  const generatePDF = (payment: WeeklyPayment) => {
    const doc = new jsPDF();
    const margin = 20;
    let y = 30;

    // Header
    doc.setFontSize(22);
    doc.setTextColor(33, 33, 33);
    doc.text('Recibo de Pagamento Semanal', margin, y);

    y += 10;
    doc.setFontSize(12);
    doc.setTextColor(100, 100, 100);
    doc.text(`Período: ${payment.startDate} a ${payment.endDate}`, margin, y);

    y += 15;
    doc.setDrawColor(200, 200, 200);
    doc.line(margin, y, 190, y);
    y += 10;

    // Workers Details
    payment.workers.forEach((worker) => {
      const daysWorked = DAYS_OF_WEEK.filter(d => worker.attendance[d.key as keyof Attendance]);
      const total = calculateWorkerTotal(worker);

      if (daysWorked.length > 0) {
        doc.setFontSize(14);
        doc.setTextColor(0, 0, 0);
        doc.setFont('helvetica', 'bold');
        doc.text(`${worker.name} (${worker.role})`, margin, y);

        y += 7;
        doc.setFontSize(11);
        doc.setFont('helvetica', 'normal');
        doc.setTextColor(80, 80, 80);

        const daysText = daysWorked.map(d => d.label).join(', ');
        doc.text(`Dias: ${daysText} (${daysWorked.length} dias)`, margin, y);

        y += 6;
        doc.text(`Valor Diária: R$ ${worker.dailyRate.toFixed(2)}`, margin, y);

        doc.setFont('helvetica', 'bold');
        doc.setTextColor(180, 120, 0);
        const subtotalText = `Subtotal: R$ ${total.toFixed(2)}`;
        const textWidth = doc.getTextWidth(subtotalText);
        doc.text(subtotalText, 190 - textWidth, y);

        y += 12;
        doc.setDrawColor(240, 240, 240);
        doc.line(margin, y, 190, y);
        y += 10;
      }
    });

    // Grand Total
    y += 5;
    doc.setFontSize(18);
    doc.setTextColor(0, 0, 0);
    const totalLabel = "TOTAL GERAL:";
    const totalValue = `R$ ${payment.totalAmount.toFixed(2)}`;
    doc.text(totalLabel, margin, y);
    const valWidth = doc.getTextWidth(totalValue);
    doc.text(totalValue, 190 - valWidth, y);

    // Footer
    y = 280;
    doc.setFontSize(10);
    doc.setTextColor(150, 150, 150);
    doc.text('Gerado via Gestão de Obra - Acidio & Equipe', margin, y);

    doc.save(`Recibo_Obra_${payment.endDate.replace(/\//g, '-')}.pdf`);
  };

  const handleSaveWeek = () => {
    const total = calculateGrandTotal();
    if (total === 0) {
      alert("Nenhum dia de trabalho registrado!");
      return;
    }

    const today = new Date();
    const lastMonday = new Date(today);
    lastMonday.setDate(today.getDate() - (today.getDay() === 0 ? 6 : today.getDay() - 1));

    const newPayment: WeeklyPayment = {
      id: Date.now().toString(),
      startDate: lastMonday.toLocaleDateString('pt-BR'),
      endDate: today.toLocaleDateString('pt-BR'),
      workers: JSON.parse(JSON.stringify(workers)),
      totalAmount: total
    };

    setHistory(prev => [newPayment, ...prev]);
    alert("Semana salva com sucesso no histórico!");
  };

  const handleGenerateReceipt = async () => {
    const total = calculateGrandTotal();
    if (total === 0) {
      alert("Por favor, marque pelo menos um dia trabalhado.");
      return;
    }

    setIsProcessing(true);
    setReceiptText(null);

    const today = new Date();
    const lastMonday = new Date(today);
    lastMonday.setDate(today.getDate() - (today.getDay() === 0 ? 6 : today.getDay() - 1));

    const currentPayment: WeeklyPayment = {
      id: 'current',
      startDate: lastMonday.toLocaleDateString('pt-BR'),
      endDate: today.toLocaleDateString('pt-BR'),
      workers: workers,
      totalAmount: total
    };

    try {
      // 1. Gerar PDF (Será baixado automaticamente pelo navegador)
      generatePDF(currentPayment);

      // 2. Gerar texto para WhatsApp via Gemini
      const text = await generateReceiptText(currentPayment);
      setReceiptText(text);

      // 3. Redirecionar para WhatsApp com o número atualizado
      const waUrl = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`;
      window.open(waUrl, '_blank');

    } catch (error) {
      console.error("Erro no processo de recibo:", error);
      alert("Houve um erro ao processar o recibo, mas o PDF pode ter sido baixado.");
    } finally {
      setIsProcessing(false);
    }
  };

  return (
    <div className="min-h-screen pb-20">
      {/* Header */}
      <header className="bg-yellow-500 text-slate-900 shadow-md sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-6 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Calculator className="w-8 h-8" />
            <h1 className="text-2xl font-bold tracking-tight">Gestão de Obra</h1>
          </div>
          <nav className="flex bg-yellow-600 rounded-lg p-1">
            <button 
              onClick={() => setView('current')}
              className={`px-4 py-2 rounded-md transition-colors ${view === 'current' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Semana Atual
            </button>
            <button 
              onClick={() => setView('history')}
              className={`px-4 py-2 rounded-md transition-colors ${view === 'history' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Histórico
            </button>
          </nav>
        </div>
      </header>

      <main className="max-w-4xl mx-auto px-4 mt-8">
        {view === 'current' ? (
          <div className="space-y-6">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-2 text-slate-600">
                <Calendar className="w-5 h-5" />
                <span className="font-medium">Resumo da Frequência</span>
              </div>
              <div className="text-sm text-slate-500 bg-white px-3 py-1 rounded-full border">
                R$ 180 (Acidio) | R$ 120 (Neto)
              </div>
            </div>

            {workers.map(worker => (
              <div key={worker.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
                <div className="p-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                  <div>
                    <h3 className="font-bold text-lg text-slate-800">{worker.name}</h3>
                    <p className="text-sm text-slate-500">{worker.role} • R$ {worker.dailyRate}/dia</p>
                  </div>
                  <div className="text-right">
                    <p className="text-xs text-slate-400 uppercase font-bold">Total Parcial</p>
                    <p className="text-xl font-bold text-yellow-600">R$ {calculateWorkerTotal(worker).toFixed(2)}</p>
                  </div>
                </div>

                <div className="p-4 grid grid-cols-3 sm:grid-cols-6 gap-3">
                  {DAYS_OF_WEEK.map(day => (
                    <button
                      key={day.key}
                      onClick={() => toggleAttendance(worker.id, day.key as keyof Attendance)}
                      className={`flex flex-col items-center justify-center p-3 rounded-lg border-2 transition-all ${
                        worker.attendance[day.key as keyof Attendance]
                          ? 'border-yellow-500 bg-yellow-50 text-yellow-700'
                          : 'border-slate-100 bg-white text-slate-400'
                      }`}
                    >
                      <span className="text-xs font-bold uppercase mb-1">{day.label}</span>
                      {worker.attendance[day.key as keyof Attendance] ? (
                        <CheckSquare className="w-5 h-5" />
                      ) : (
                        <div className="w-5 h-5 border-2 border-slate-200 rounded-sm" />
                      )}
                    </button>
                  ))}
                </div>
              </div>
            ))}

            {/* Current Summary Bar */}
            <div className="bg-slate-900 text-white rounded-xl p-6 shadow-xl flex flex-col md:flex-row justify-between items-center gap-6">
              <div>
                <p className="text-slate-400 text-sm uppercase tracking-wider font-bold">Total da Semana</p>
