                  onClick={handleGenerateReceipt}
                  disabled={isProcessing}
                  className={`flex-1 md:flex-none flex items-center justify-center gap-2 px-6 py-3 rounded-lg font-bold transition-colors ${
                    isProcessing ? 'bg-slate-700 cursor-not-allowed' : 'bg-slate-800 hover:bg-slate-700 text-white'
                  }`}
                >
                  {isProcessing ? (
                    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  ) : (
                    <FileText className="w-5 h-5" />
