import { GoogleGenAI } from "@google/genai";
import { WeeklyPayment } from "../types";

export const generateReceiptText = async (payment: WeeklyPayment): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const workerSummary = payment.workers.map(w => {
    const daysWorked = Object.values(w.attendance).filter(Boolean).length;
    const total = daysWorked * w.dailyRate;
    if (daysWorked === 0) return null;
    return `* **${w.name} (${w.role}):** ${daysWorked} dias trabalhados (R$ ${w.dailyRate.toFixed(2).replace('.', ',')}/dia) = **R$ ${total.toFixed(2).replace('.', ',')}**`;
  }).filter(Boolean).join('\n');

  const prompt = `
    Aja como um administrador de obras. Gere EXATAMENTE o texto abaixo preenchendo as informações dinâmicas.
    NÃO adicione introduções ou conclusões extras além do solicitado.

    FORMATO SOLICITADO:
    ---
    **Fechamento de Pagamentos – Semanal**

    Seguem os valores referentes aos serviços prestados no período de ${payment.startDate} a ${payment.endDate}:

    ${workerSummary}

    💰 **Total Geral da Semana: R$ ${payment.totalAmount.toFixed(2).replace('.', ',')}**

    Qualquer dúvida, estou à disposição. 
    Atenciosamente,

    ** Leonardo **

    *"Seguem os comprovantes em anexo."*
    ---

    Certifique-se de usar negritos (**) e itálicos (*) conforme o modelo. O emoji de dinheiro deve ser incluído no total.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });
    return response.text || "Erro ao gerar resumo.";
  } catch (error) {
    console.error("Error generating receipt:", error);
    return "Desculpe, não foi possível gerar o resumo automático agora.";
  }
};

