          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-400 text-[10px] px-4 pb-4">
        <p>WhatsApp: 21 99739-1448 | Obra do Acidio</p>
      </footer>
    </div>
  );
};

