import React, { useState, useEffect, useRef } from 'react';
import { Worker, WorkerType, WeeklyPayment, DAYS_OF_WEEK, Attendance } from './types';
import { generateReceiptText } from './services/geminiService';
import html2canvas from 'html2canvas';
import { 
  Users, 
  Calendar, 
  Trash2, 
  Save, 
  MessageSquare, 
  CheckSquare, 
  History as HistoryIcon,
  ChevronLeft,
  ChevronRight,
  Calculator,
  Send,
  X,
  Copy
} from 'lucide-react';

const INITIAL_WORKERS: Worker[] = [
  {
    id: '1',
    name: 'Acidio',
    role: WorkerType.PEDREIRO,
    dailyRate: 180,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  },
  {
    id: '2',
    name: 'Neto',
    role: WorkerType.AJUDANTE,
    dailyRate: 120,
    attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
  }
];

const WHATSAPP_NUMBER = "5521997391448";

const App: React.FC = () => {
  const [workers, setWorkers] = useState<Worker[]>(() => {
    const saved = localStorage.getItem('current_week_workers');
    return saved ? JSON.parse(saved) : INITIAL_WORKERS;
  });

  const [history, setHistory] = useState<WeeklyPayment[]>(() => {
    const saved = localStorage.getItem('payment_history');
    return saved ? JSON.parse(saved) : [];
  });

  const [view, setView] = useState<'current' | 'history'>('current');
  const [selectedHistoryId, setSelectedHistoryId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [receiptText, setReceiptText] = useState<string | null>(null);
  const [showClipboardNotice, setShowClipboardNotice] = useState(false);

  const captureRef = useRef<HTMLDivElement>(null);
  const currentViewRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    localStorage.setItem('current_week_workers', JSON.stringify(workers));
  }, [workers]);

  useEffect(() => {
    localStorage.setItem('payment_history', JSON.stringify(history));
  }, [history]);

  const toggleAttendance = (workerId: string, day: keyof Attendance) => {
    setWorkers(prev => prev.map(w => 
      w.id === workerId 
        ? { ...w, attendance: { ...w.attendance, [day]: !w.attendance[day] } }
        : w
    ));
  };

  const toggleHistoryAttendance = (historyId: string, workerId: string, day: keyof Attendance) => {
    setHistory(prev => prev.map(item => {
      if (item.id !== historyId) return item;
      const updatedWorkers = item.workers.map(w => 
        w.id === workerId 
          ? { ...w, attendance: { ...w.attendance, [day]: !w.attendance[day] } }
          : w
      );
      const newTotal = updatedWorkers.reduce((acc, w) => acc + (Object.values(w.attendance).filter(Boolean).length * w.dailyRate), 0);
      return { ...item, workers: updatedWorkers, totalAmount: newTotal };
    }));
  };

  const calculateWorkerTotal = (worker: Worker) => {
    const daysWorked = Object.values(worker.attendance).filter(Boolean).length;
    return daysWorked * worker.dailyRate;
  };

  const calculateGrandTotal = () => {
    return workers.reduce((acc, w) => acc + calculateWorkerTotal(w), 0);
  };

  const handleSaveWeek = () => {
    const total = calculateGrandTotal();
    if (total === 0) {
      alert("Nenhum dia de trabalho registrado!");
      return;
    }

    const today = new Date();
    const lastMonday = new Date(today);
    lastMonday.setDate(today.getDate() - (today.getDay() === 0 ? 6 : today.getDay() - 1));

    const newPayment: WeeklyPayment = {
      id: Date.now().toString(),
      startDate: lastMonday.toLocaleDateString('pt-BR'),
      endDate: today.toLocaleDateString('pt-BR'),
      workers: JSON.parse(JSON.stringify(workers)),
      totalAmount: total
    };

    setHistory(prev => [newPayment, ...prev]);
    setWorkers(prev => prev.map(w => ({
      ...w,
      attendance: { monday: false, tuesday: false, wednesday: false, thursday: false, friday: false, saturday: false }
    })));
    alert("Semana salva com sucesso no histórico!");
  };

  const handleDeleteHistory = (id: string) => {
    const firstConfirm = window.confirm("Deseja realmente apagar este registro do histórico?");
    if (firstConfirm) {
      const secondConfirm = window.confirm("ATENÇÃO: Esta ação não pode ser desfeita. Confirmar exclusão definitiva?");
      if (secondConfirm) {
        setHistory(currentHistory => {
          const newHistory = currentHistory.filter(item => item.id !== id);
          localStorage.setItem('payment_history', JSON.stringify(newHistory));
          return newHistory;
        });
        setSelectedHistoryId(null);
      }
    }
  };

  const copyToClipboard = async (element: HTMLElement) => {
    try {
      const canvas = await html2canvas(element, {
        scale: 2,
        backgroundColor: '#ffffff',
        logging: false,
        useCORS: true,
      });

      return new Promise<void>((resolve, reject) => {
        canvas.toBlob(async (blob) => {
          if (!blob) return reject(new Error("Erro ao criar imagem."));
          try {
            const data = [new ClipboardItem({ 'image/png': blob })];
            await navigator.clipboard.write(data);
            resolve();
          } catch (err) {
            reject(err);
          }
        }, 'image/png');
      });
    } catch (err) {
      console.error("Erro ao capturar print:", err);
      throw err;
    }
  };

  const handleGenerateReceipt = async (paymentToProcess: WeeklyPayment) => {
    setIsProcessing(true);
    setReceiptText(null);

    try {
      if (captureRef.current) {
        try {
          await copyToClipboard(captureRef.current);
          setShowClipboardNotice(true);
          setTimeout(() => setShowClipboardNotice(false), 5000);
        } catch (clipboardError) {
          console.warn("Clipboard error:", clipboardError);
        }
      }

      const text = await generateReceiptText(paymentToProcess);
      setReceiptText(text);
      const waUrl = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(text)}`;
      window.open(waUrl, '_blank');
    } catch (error) {
      console.error("Receipt generation error:", error);
      alert("Erro ao processar resumo do WhatsApp.");
    } finally {
      setIsProcessing(false);
    }
  };

  const selectedPayment = history.find(h => h.id === selectedHistoryId);

  return (
    <div className="min-h-screen pb-20">
      <header className="bg-yellow-500 text-slate-900 shadow-md sticky top-0 z-10">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-2">
            <Calculator className="w-6 h-6" />
            <h1 className="text-xl font-bold tracking-tight">Gestão de Obra</h1>
          </div>
          <nav className="flex bg-yellow-600 rounded-lg p-1">
            <button 
              onClick={() => { setView('current'); setSelectedHistoryId(null); }}
              className={`px-3 py-1.5 text-sm rounded-md transition-colors ${view === 'current' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Semana
            </button>
            <button 
              onClick={() => setView('history')}
              className={`px-3 py-1.5 text-sm rounded-md transition-colors ${view === 'history' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Histórico
            </button>
          </nav>
        </div>
      </header>

      {showClipboardNotice && (
        <div className="fixed bottom-24 left-1/2 -translate-x-1/2 z-50 bg-slate-900 text-white px-4 py-2 rounded-full shadow-2xl flex items-center gap-2 animate-bounce border border-yellow-500/50">
          <Copy className="w-4 h-4 text-yellow-500" />
          <span className="text-xs font-bold">Print copiado! Cole no WhatsApp.</span>
        </div>
      )}

      <main className="max-w-4xl mx-auto px-4 mt-6">
        {view === 'current' ? (
          <div className="space-y-4">
            <div className="flex items-center justify-between mb-2">
              <div className="flex items-center gap-2 text-slate-600 text-sm">
                <Calendar className="w-4 h-4" />
                <span className="font-medium">Frequência Atual</span>
              </div>
              <div className="text-xs text-slate-500 bg-white px-2 py-0.5 rounded-full border">
                Acid. R$ 180 | Neto R$ 120
              </div>
            </div>

            <div ref={currentViewRef} className="space-y-4">
              {workers.map(worker => (
                <div key={worker.id} className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden hover:shadow-md transition-shadow">
                  <div className="p-2 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div>
                      <h3 className="font-bold text-sm text-slate-800">{worker.name}</h3>
                      <p className="text-[10px] text-slate-500">{worker.role} • R$ {worker.dailyRate}</p>
                    </div>
                    <div className="text-right">
                      <p className="text-[10px] text-slate-400 uppercase font-bold">Total</p>
                      <p className="text-base font-bold text-yellow-600">R$ {calculateWorkerTotal(worker).toFixed(2)}</p>
                    </div>
                  </div>
                  <div className="p-1 grid grid-cols-6 gap-1">
                    {DAYS_OF_WEEK.map(day => (
                      <button
                        key={day.key}
                        onClick={() => toggleAttendance(worker.id, day.key as keyof Attendance)}
                        className={`flex flex-col items-center justify-center py-1 rounded border transition-all ${
                          worker.attendance[day.key as keyof Attendance]
                            ? 'border-yellow-500 bg-yellow-50 text-yellow-700'
                            : day.key === 'saturday'
                              ? 'border-slate-200 bg-slate-100 text-slate-400'
                              : 'border-slate-50 bg-white text-slate-300'
                        }`}
                      >
                        <span className="text-[8px] font-bold uppercase mb-0.5">{day.label}</span>
                        {worker.attendance[day.key as keyof Attendance] 
                          ? <CheckSquare className="w-3.5 h-3.5" /> 
                          : <div className={`w-3.5 h-3.5 border rounded-sm ${day.key === 'saturday' ? 'border-slate-300' : 'border-slate-100'}`} />}
                      </button>
                    ))}
                  </div>
                </div>
              ))}
            </div>

            <div className="bg-slate-900 text-white rounded-xl p-4 shadow-xl flex flex-col md:flex-row justify-between items-center gap-4">
              <div className="text-center md:text-left">
                <p className="text-slate-400 text-[10px] uppercase tracking-wider font-bold">Total da Semana</p>
                <h2 className="text-3xl font-extrabold">R$ {calculateGrandTotal().toFixed(2)}</h2>
              </div>
              <div className="flex w-full md:w-auto">
                <button onClick={handleSaveWeek} className="flex-1 md:w-64 flex items-center justify-center gap-2 bg-yellow-500 hover:bg-yellow-400 text-slate-900 px-4 py-4 rounded-lg text-sm font-bold transition-all shadow-lg active:scale-95">
                  <Save className="w-5 h-5" />
                  Salvar Semana
                </button>
              </div>
            </div>
          </div>
        ) : (
          <div className="space-y-3">
            {!selectedHistoryId ? (
              <>
                <div className="flex items-center gap-2 text-slate-600 mb-4 text-sm">
                  <HistoryIcon className="w-4 h-4" />
                  <span className="font-medium">Histórico de Pagamentos</span>
                </div>
                {history.length === 0 ? (
                  <div className="bg-white rounded-xl p-10 text-center border-2 border-dashed border-slate-200">
                    <Users className="w-10 h-10 text-slate-200 mx-auto mb-3" />
                    <p className="text-slate-400 text-sm">Nenhum histórico disponível.</p>
                  </div>
                ) : (
                  history.map(item => (
                    <div key={item.id} onClick={() => setSelectedHistoryId(item.id)} className="bg-white rounded-lg border border-slate-200 p-3 flex justify-between items-center gap-4 hover:border-yellow-400 transition-colors cursor-pointer group">
                      <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-yellow-100 text-yellow-700 rounded-full flex items-center justify-center font-bold text-xs">{item.startDate.split('/')[0]}</div>
                        <div>
                          <p className="font-bold text-sm text-slate-800">{item.startDate} — {item.endDate}</p>
                          <p className="text-[10px] text-slate-400">
                            {item.workers.map(w => `${w.name} (${Object.values(w.attendance).filter(Boolean).length}d)`).join(', ')}
                          </p>
