                      </div>
                      <div className="text-right">
                        <p className="text-[10px] text-slate-400 font-bold uppercase">Total Pago</p>
                        <p className="text-2xl font-black text-yellow-600">R$ {selectedPayment?.totalAmount.toFixed(2)}</p>
                      </div>
                    </div>

                    <div className="space-y-2 mb-2">
                      {selectedPayment?.workers.map(worker => {
                        const daysCount = Object.values(worker.attendance).filter(Boolean).length;
                        const workerSubtotal = daysCount * worker.dailyRate;

                        return (
                          <div key={worker.id} className="border border-slate-100 rounded-lg p-2 bg-slate-50/50">
                            <div className="flex justify-between items-center mb-1">
                              <div className="flex items-baseline gap-1.5">
                                <span className="font-bold text-xs text-slate-800">{worker.name}</span>
                                <span className="text-[9px] text-slate-500 uppercase">
                                  ({daysCount}d x R$ {worker.dailyRate})
                                </span>
                              </div>
                              <div className="text-right">
                                <span className="text-xs font-bold text-yellow-600">
                                  R$ {workerSubtotal.toFixed(2)}
                                </span>
