          <Copy className="w-4 h-4 text-yellow-500" />
          <span className="text-xs font-bold uppercase">Print copiado! Cole no WhatsApp</span>
        </div>
      )}

      <main className="max-w-4xl mx-auto px-4 mt-6">
        {view === 'current' ? (
          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <span className="text-slate-500 text-xs font-bold uppercase tracking-widest">Frequência Semanal</span>
              <span className="text-[10px] bg-white border px-2 py-0.5 rounded text-slate-400">R$ 180 / R$ 120</span>
            </div>

            <div className="space-y-4">
