      if (navigator.share && imageBlob && navigator.canShare && navigator.canShare({ files: [new File([imageBlob], 'recibo.png', { type: 'image/png' })] })) {
        try {
          const file = new File([imageBlob], `recibo_${payment.startDate.replace(/\//g, '-')}.png`, { type: 'image/png' });
