  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <header className="bg-yellow-500 text-slate-900 shadow-md sticky top-0 z-30">
        <div className="max-w-4xl mx-auto px-4 py-4 flex justify-between items-center">
