              onClick={() => { setView('current'); setSelectedHistoryId(null); }}
              className={`px-4 py-1.5 text-sm rounded-md transition-all ${view === 'current' ? 'bg-yellow-400 font-bold shadow-sm' : 'text-yellow-100'}`}
            >
              Semana
