    try {
      const canvas = await html2canvas(element, {
        scale: 2,
        backgroundColor: '#ffffff',
        useCORS: true,
        logging: false
      });
      return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
    } catch (err) {
      console.error("Erro ao capturar imagem do recibo:", err);
      return null;
    }
  };

  const handleGenerateReceipt = async (payment: WeeklyPayment) => {
    if (isProcessing) return;
    setIsProcessing(true);

    try {
      const text = await generateReceiptText(payment);
      let imageBlob: Blob | null = null;

      if (captureRef.current) {
        imageBlob = await getReceiptBlob(captureRef.current);
      }

      // Tentativa de Compartilhamento Nativo (Mobile)
      let shared = false;
      if (navigator.share && imageBlob) {
        const file = new File([imageBlob], `recibo_${payment.startDate.replace(/\//g, '-')}.png`, { type: 'image/png' });
        try {
          if (navigator.canShare && navigator.canShare({ files: [file] })) {
            await navigator.share({
              title: 'Recibo de Obra',
              text: text,
              files: [file]
            });
            shared = true;
          }
