      // Nota: navigator.clipboard.write([ClipboardItem]) após await costuma falhar por perda de gesto do usuário.
      // Por isso, abrimos o WhatsApp diretamente com o texto.
      window.open(waUrl, '_blank');

    } catch (error) {
      console.error("Erro geral no processo:", error);
      alert("Erro ao preparar WhatsApp. Tente novamente.");
    } finally {
      setIsProcessing(false);
    }
  };

